import{_ as a,a as t,b as r,c as e}from"./chunks/btn_privacy_settings.YFoaKcfF.js";import{_ as i,o as l,c as s,a0 as n}from"./chunks/framework.DRjqbEpm.js";const k=JSON.parse('{"title":"2. 控制面板詳解","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dashboard.md","filePath":"guide/dashboard.md"}'),c={name:"guide/dashboard.md"};function d(_,o,u,p,g,h){return l(),s("div",null,[...o[0]||(o[0]=[n('<h1 id="_2-控制面板詳解" tabindex="-1">2. 控制面板詳解 <a class="header-anchor" href="#_2-控制面板詳解" aria-label="Permalink to &quot;2. 控制面板詳解&quot;">​</a></h1><p>V-Train 的控制面板是您管理所有設定的核心樞紐。</p><blockquote><p><img src="'+a+'" alt="控制面板主畫面"></p></blockquote><h3 id="狀態監控區" tabindex="-1">狀態監控區 <a class="header-anchor" href="#狀態監控區" aria-label="Permalink to &quot;狀態監控區&quot;">​</a></h3><ul><li><strong>自動監控 (Monitoring) / 手動暫停 (Stealth)</strong>： <blockquote><p><img src="'+t+'" alt="監控開關"> 透過開關可以隨時暫停 V-Train 的追蹤功能。開啟「關閉瀏覽器即自動暫停」可在您離開時保護隱私。</p></blockquote></li><li><strong>啟用快捷互動按鈕</strong>：控制影片畫面右下角是否要顯示「按讚/收藏/截圖」的懸浮面板。</li><li><strong>Show Monitor Panel</strong>：決定是否在網頁左下角顯示 V-Train 的系統狀態小黑窗。</li><li><strong>進度條顏色 (Progress Bar Color)</strong>：點擊色塊可以自由更改您喜歡的進度條顏色（預設為紅色）。</li></ul><h3 id="捷徑與管理區" tabindex="-1">捷徑與管理區 <a class="header-anchor" href="#捷徑與管理區" aria-label="Permalink to &quot;捷徑與管理區&quot;">​</a></h3><ul><li><strong>已訓練網站 (規則管理)</strong>： <blockquote><p><img src="'+r+'" alt="規則管理按鈕"> 管理您自訂或匯入的網站適應規則。可以在這裡刪除不需要的規則，或是將規則「複製序號」分享給其他人。</p></blockquote></li><li><strong>Bookmark Vault (書籤庫)</strong>：<code>[Pro 限定]</code> 進入全螢幕的書籤管理中心。</li><li><strong>設定密碼 / 清除資料</strong>： <blockquote><p><img src="'+e+'" alt="隱私設定"> 設定專屬的隱私密碼鎖。每次開啟面板時需輸入密碼才能查看數據。點擊「清除資料」可一鍵刪除所有本地觀看紀錄與書籤（不影響 Pro 狀態與規則）。</p></blockquote></li></ul>',7)])])}const q=i(c,[["render",d]]);export{k as __pageData,q as default};
